python - <<'PY'
import json,struct
p='/tmp/opencode/uploads/2c2f39e0-7529-4899-83ca-3001ceb9a50b/model_1794409020604.glb'
with open(p,'rb') as f:
    magic,version,length=struct.unpack('<III',f.read(12))
    while True:
        hdr=f.read(8)
        if not hdr: break
        chunk_len, chunk_type = struct.unpack('<I4s',hdr)
        data=f.read(chunk_len)
        if chunk_type==b'JSON':
            obj=json.loads(data)
            print('JSON keys',obj.keys())
            for k in ['nodes','meshes','materials','scenes','buffers','bufferViews','accessors']:
                if k in obj:
                    print(k, type(obj[k]).__name__, len(obj[k]) if hasattr(obj[k],'__len__') else 'n/a')
            if 'nodes' in obj:
                print('node names', [n.get('name') for n in obj['nodes'][:10]])
            if 'meshes' in obj:
                print('mesh names', [m.get('name') for m in obj['meshes'][:10]])
            if 'materials' in obj:
                print('material names', [m.get('name') for m in obj['materials'][:10]])
            if 'scenes' in obj:
                print('scene nodes', obj['scenes'][0].get('nodes'))
            break
