  white: mat(0xf3edda), lamp: new THREE.MeshStandardMaterial({ color: 0xffe6a3, emissive: 0xffbd4d, emissiveIntensity: 1.25 }),
};

const gltfLoader = new GLTFLoader();
let importedModel = null;
const modelUrl = '/tmp/opencode/uploads/2c2f39e0-7529-4899-83ca-3001ceb9a50b/model_1794409020604.glb';

function loadImportedModel() {
  gltfLoader.load(
    modelUrl,
    (gltf) => {
      const model = gltf.scene;
      model.name = 'customModel';
      model.scale.setScalar(7.6);
      model.rotation.y = Math.PI;
      model.position.set(0, 0, -34);
      model.traverse((obj) => {
        if (obj.isMesh) {
          obj.castShadow = true;
          obj.receiveShadow = true;
        }
      });
      scene.add(model);
      importedModel = model;
      showToast('CUSTOM LANDMARK LOADED');
    },
    undefined,
    (error) => {
      console.warn('Could not load model:', error);
    }
  );
}

